// initial reduces a path segment to its first rune, keeping a leading dot.
func initial(seg string) string {
	runes := []rune(seg)
	switch {
	case len(runes) <= 1:
		return seg
	case runes[0] == '.':
		return string(runes[:2])
	default:
		return string(runes[:1])
	}
}
